# Generates the starter description files in Codebook/descriptions/.
# WARNING: re-running overwrites any hand edits to those .md files.
import pandas as pd, re, os
d=pd.read_csv('Codebook/sona_codebook.csv').fillna('')
INTRO={
'STUDY INTRODUCTION':"Opening page of the SONA survey. Participants read study instructions (no save-and-return option; complete in one sitting, about 1–2 hours, 2 SONA credits) and agree to have their responses collected, stored, and used for research. Answering **No** to `intro_consent` ends the survey (REDCap stop action on 0).",
'RESEARCH INFORMATION SHEET':"UT Austin research information sheet for *Exercise Motivations and Eating Behaviors* (Investigator: Katherine Schaumberg, PhD). Participants must select **I acknowledge** (`ris_yes`) to proceed. The consent PDF (SONA Consent 5.28.26) is attached to `sona_ris` in REDCap.",
'STUDY ID':"Participant identifiers. `unique_sona_id` is a participant-created ID (last four digits of phone number + two-digit day of birth) used to link records; `sona_id` is a hidden field used by staff for credit approval.",
'BDI-II':"The **Beck Depression Inventory-II** (Beck, Steer, & Brown, 1996) is a 21-item self-report questionnaire measuring severity of depressive symptoms over the past two weeks. Each item is a group of four statements scored 0–3.\n\n**Scoring**\n\nA total sum score (0–63) is computed, with higher scores indicating more severe depressive symptoms. No REDCap calculated field is included for the BDI-II in SONA; score from the item variables.",
'ED 100K PLUS':"The **ED100k-Plus** is a lab-adapted version of the ED100K.V3 (Thornton et al., 2018), a self-report eating disorder assessment based on the SCID-5. It assesses current and lifetime eating disorder symptoms and includes items from the [Dieting and Weight History Questionnaire](https://pubmed.ncbi.nlm.nih.gov/23220357/) (variables beginning `wdqhq_`), lab ED-history items (`edhistory_`, `dcf_`), EDE-Q items (`edeq_`), and EDDS items (`edds_`). It covers weight history (current, highest, lowest, set-point weight and BMI), menstrual history, binge eating, compensatory behaviors, driven exercise, restriction, and weight/shape concern. This measure is not yet validated.\n\n**Scoring**\n\nWeights entered in kilograms are converted to pounds (`*_correct_plus`), BMIs and weight-suppression values are computed, and diagnostic variables follow DSM-5 algorithms for threshold and sub-clinical (past and current) Anorexia Nervosa, Atypical Anorexia Nervosa, Bulimia Nervosa, Binge Eating Disorder, and Purging Disorder. Diagnostic variables are coded 0 = criteria not met, 1 = criteria met.",
'OBSESSIVE-COMPULSIVE INVENTORY-12':"The **Obsessive-Compulsive Inventory-12** (OCI-12; Abramovitch, Abramowitz, & McKay, 2021) is a 12-item self-report measure of obsessive-compulsive symptoms (checking, ordering, obsessing, washing) rated 0 (*Not at all*) to 4 (*Extremely*) for distress over the past month.",
'EATING PATHOLOGY SYMPTOMS INVENTORY':"The **Eating Pathology Symptoms Inventory** (EPSI; Forbush et al., 2013) is a 45-item self-report measure of eating disorder symptoms over the past four weeks, rated 0 (*Never*) to 4 (*Very often*). It yields eight subscales: Body Dissatisfaction, Binge Eating, Cognitive Restraint, Purging, Restricting, Excessive Exercise, Negative Attitudes toward Obesity, and Muscle Building.\n\n**Note on `_merged` variables:** the Excessive Exercise and Muscle Building items were also administered within the *Exercise Questions Compiled* form; those copies carry the suffix `_merged` (e.g. `epsi_5_exercise_alot_merged`) and are listed here alongside the main EPSI form.",
'EATING FEARS QUESTIONNAIRE':"The **Eating Disorder Fear Questionnaire** (EFQ) is a 20-item self-report measure of fears related to eating, weight gain, and their consequences, rated 0 (*Not at all*) to 6 (*Very much so*). It yields a total score and five subscales: Fear of Weight Gain, Fear of Social Consequences, Fear of Personal Consequences, Fear of Physical Sensations, and Fear of Social Eating.",
'STATE-TRAIT ANXIETY INVENTORY':"The **State-Trait Anxiety Inventory** (STAI; Spielberger et al., 1983) is a 40-item self-report measure. Items 1–20 assess state anxiety (how one feels *right now*; *Not at all* to *Very much so*) and items 21–40 assess trait anxiety (how one *generally* feels; *Almost never* to *Almost always*). In SONA, items are coded 0–3.",
'COMPULSIVE EXERCISE TEST':"The **Compulsive Exercise Test** (CET; Taranis, Touyz, & Meyer, 2011) is a 24-item self-report questionnaire assessing maladaptive exercise, rated 0 (*Never true*) to 5 (*Always true*). It has five subscales: Avoidance and Rule-Driven Behavior; Weight Control Exercise; Mood Improvement; Lack of Exercise Enjoyment; Exercise Rigidity.\n\nIn SONA, the CET was administered in the *Exercise Questions Compiled* form, so all variables carry the suffix `_merged`. Reverse-keyed items are coded in reverse directly in REDCap (5 = *Never true*).",
'DRIVE FOR MUSCULARITY':"The **Drive for Muscularity Scale** (DMS; McCreary & Sasse, 2000) is a 15-item questionnaire assessing attitudes and behaviors reflecting a desire to be more muscular. In SONA, items are coded 5 (*Always*) to 0 (*Never*), so higher scores indicate greater drive for muscularity.\n\nAdministered in the *Exercise Questions Compiled* form; all variables carry the suffix `_merged`.",
'EXERCISE DEPENDENCE SCALE':"The **Exercise Dependence Scale** (EDS-21; Hausenblas & Symons Downs, 2002) is a 21-item measure of exercise dependence symptoms based on DSM substance-dependence criteria, rated from *Never* to *Always* (coded 0–5 in SONA). It has seven subscales: Withdrawal, Continuance, Tolerance, Lack of Control, Reduction in Other Activities, Time, and Intention Effects.\n\nAdministered in the *Exercise Questions Compiled* form; all variables carry the suffix `_merged`.",
'EXERCISE QUESTIONS COMPILED':"*Exercise Questions Compiled* is the REDCap form that housed the Compulsive Exercise Test, Drive for Muscularity Scale, Exercise Dependence Scale, and the EPSI exercise/muscle-building items. Those variables are documented under their own measures above; only the form-status field remains here.",
'ANALOGOUS EXERCISE DECISIONS':"The **Analogous Exercise Decisions** (AED – Brief) task is a lab-developed behavioral-economic questionnaire assessing preferences between exercise and alternative rewards. Participants choose between a planned workout (30 minutes or 1 hour) and increasing amounts of money, and indicate whether they would eat increasing additional snack amounts (kcal) in order to exercise for 30 minutes or 1 hour.\n\n**Scoring**\n\nBreakpoints are determined for each series as the first point at which the participant chooses the alternative over exercise (money series) or declines the snack requirement (snack series). No REDCap calculated fields are included.",
"ATHLETES' RELATIONSHIP WITH TRAINING SCALE":"The **Athletes' Relationship with Training Scale** (ART) is a 15-item self-report questionnaire assessing unhealthy training behaviors and beliefs. Items are rated 0–4 (frequency or agreement), with a −9 *N/A* option for items that do not apply.",
'FUNCTIONAL ASSESSMENT OF DRIVEN EXERCISE':"The **Functional Assessment of Driven Exercise** (FADE) assesses the functions that exercise serves, adapted from the four-function model of behavior (automatic/social × positive/negative reinforcement). Participants rate how often they exercise for each reason from 0 (*Never*) to 3 (*Often*).\n\nNote: `fade_17_attention` (*To get attention*) and `fade_24_avoid_attention` are substantive items, not attention checks.",
'DATA COLLECTION FORM':"The brief **Data Collection Form** (DCF) captures demographics and history: age, sex assigned at birth, gender identity, transgender identity, pronouns, sexual identity, race, Hispanic ethnicity, education, medical and psychiatric history and treatment, ADHD/autism diagnoses, medical conditions, marijuana, alcohol, and steroid use (including quit attempts), and family history of eating and other psychiatric disorders.\n\nFields `dcf_mj_age_1`…`dcf_relate_dx_5` are cells of embedded tables and have no label of their own in REDCap; their labels here were derived from the table they belong to (see the *Label Source* column in `sona_codebook.xlsx`).",
'EXERCISE AND EATING DISORDERS QUESTIONNAIRE':"Items from the **Exercise and Eating Disorders** questionnaire (EED) assessing enjoyment of physical activity, exercising with others or for health, and awareness of bodily cues (tiredness, thirst, hunger, fitness). Rated 0 (*Never*) to 5 (*Always*).",
'TRADITIONAL MASCULINITY-FEMININITY SCALE':"The **Traditional Masculinity-Femininity Scale** (TMF; Kachel, Steffens, & Niedlich, 2016) is a 6-item self-report measure of gender-role self-concept. Participants rate themselves (actual and ideal self, interests, attitudes, behavior, appearance) from 1 (*Totally masculine*) to 7 (*Totally feminine*).",
'INTUITIVE EXERCISE SCALE':"The **Intuitive Exercise Scale** (Reel et al., 2016) assesses exercising in response to internal bodily cues (e.g., stopping when tired) rather than rigid rules. Items are rated 1 (*Strongly disagree*) to 5 (*Strongly agree*).",
'HYPOTHETICAL EXERCISE SCENARIOS':"Lab-developed **hypothetical scenarios** assessing persistence of exercise under barriers. Sixteen scenarios are grouped into four domains — Sickness/Feeling Unwell (`sick`), Injury (`injury`), Life Interference (`interfere`), and Social (`social`), four scenarios each. For each scenario `hypo_<n>_<domain>`:\n\n- `_1` — would you still find a way to exercise? (yes/no)\n- `_intent` — if yes, intention for exercising (checkbox: mental health, routine, physical fitness, weight control, shape control, other), with `_intent_other` free text\n- `_2` — if the scenario prevented exercise, how much would it bother you (0–10)",
'EXERCISE MOTIVATIONS INVENTORY-2':"The **Exercise Motivations Inventory-2** (EMI-2; Markland & Ingledew, 1997) is a 51-item measure of reasons for exercising (e.g., weight management, appearance, stress management, enjoyment, health, social recognition). Items complete the stem *“Personally, I exercise (or might exercise)…”* and are rated 0 (*Not at all true for me*) to 5 (*Very true for me*).",
'GODIN LEISURE-TIME EXERCISE QUESTIONNAIRE':"The **Godin Leisure-Time Exercise Questionnaire** (Godin & Shephard, 1985) asks how many times in a typical week the participant does strenuous, moderate, and mild exercise for more than 15 minutes during free time.\n\n**Scoring**\n\nA weekly leisure activity score is conventionally computed as (9 × strenuous) + (5 × moderate) + (3 × mild). No REDCap calculated field is included.",
'EATING HABITS QUESTIONNAIRE':"The **Eating Habits Questionnaire** (EHQ; Gleaves, Graham, & Ambwani, 2013) assesses orthorexic (healthy-eating–focused) attitudes and behaviors, including knowledge of healthy eating, problems associated with healthy eating, and feeling positively about healthy eating. Items are rated 1 (*False, not at all true*) to 4 (*Very true*).",
'ANALOGOUS EXERCISE DECISIONS - CONTINUOUS':"Continuous (slider) version of the Analogous Exercise Decisions task. Participants indicate the smallest amount of money ($0–100) that would lead them to skip a planned 30-minute or 1-hour workout, and the largest additional snack (0–500 kcal) they would eat in order to exercise for 30 minutes or 1 hour.",
'EXERCISE BELIEFS QUESTIONNAIRE':"The **Exercise Beliefs Questionnaire** (EBQ; Loumidis & Wells, 1998) assesses beliefs about the consequences of not exercising (e.g., social desirability, physical appearance, mental and emotional functioning, vulnerability to disease and aging). In SONA, items are rated on a 0–100 slider.",
'EDI DRIVE FOR THINNESS':"The **Eating Disorder Inventory – Drive for Thinness** subscale (EDI-DT; Garner, Olmstead, & Polivy, 1983) is a 7-item measure of excessive concern with dieting, preoccupation with weight, and fear of weight gain. In SONA, items are coded 0 (*Never or rarely*) to 4 (*Always*); `edi_sweets` is reverse-keyed in REDCap.\n\n> ⚠️ **Check before analysis:** the REDCap calculation for `edi_total` includes the attention-check item `edi_attention` in the sum. Recompute the total from the seven substantive items.",
'EXERCISE ADDICTION INVENTORY':"The **Exercise Addiction Inventory** (EAI; Terry, Szabo, & Griffiths, 2004) assesses components of behavioral addiction applied to exercise (salience, conflict, mood modification, tolerance, withdrawal, relapse). In SONA, 8 items were administered, rated 1 (*Strongly disagree*) to 6 (*Strongly agree*).",
'EATING DISORDER EXAMINATION QUESTIONNAIRE':"The **Eating Disorder Examination Questionnaire 6.0** (EDE-Q; Fairburn & Beglin, 2008) is a 28-item self-report version of the EDE assessing eating disorder attitudes and behaviors over the past 28 days. Items 1–12 and 19–21 use frequency/proportion ratings (0–6), items 13–18 are behavior counts, and items 22–28 are severity ratings (0 = *Not at all* to 6 = *Markedly*).\n\n**Scoring**\n\nFour subscales — Restraint, Eating Concern, Shape Concern, Weight Concern — are computed as item means, and the global score is the mean of the four subscales. No REDCap calculated fields are included.",
'STUDY RECRUITMENT AND RESOURCES':"End-of-survey page: thank-you and credit information, a downloadable UT mental health resources sheet, and information about other EMBARK Lab studies. Contains no participant responses other than the form-status field.",
}
def fname(m):
    k=re.sub(r'[^a-z0-9]+','_',m.lower()).strip('_'); return k+'.md'
for m,g in d.groupby('Measure',sort=False):
    parts=[INTRO[m]]
    items=g[~g['Field Type'].isin(['calc','descriptive'])&~g.Variable.str.endswith('_complete')]
    att=items[items.Label.str.contains('paying attention',case=False)]
    calcs=g[g['Field Type']=='calc']
    if len(calcs):
        parts.append('**Key Variables** (calculated in REDCap)\n\n'+'\n'.join(f'- `{r.Variable}` — {r.Label.rstrip(":").strip()}' for _,r in calcs.iterrows()))
    if len(att):
        parts.append('**Attention checks:** '+', '.join(f'`{v}`' for v in att.Variable)+' — exclude from scoring.')
    open('Codebook/descriptions/'+fname(m),'w').write('\n\n'.join(parts)+'\n')
print(sorted(os.listdir('Codebook/descriptions')))
